declare(strict_types=1);ob_start();require dirname(__DIR__).'/portal-private/bootstrap.php';$p=getenv('PORTAL_CONFIG_FILE');if(!$p||!str_ends_with($p,'config.test.php'))throw new RuntimeException('Solo pruebas.');$c=require$p;if(!str_ends_with($c['db_name'],'_test'))throw new RuntimeException('Solo base de pruebas.');$app=portal_app();$db=$app->db();$n=0;
function ok(bool$v,string$l):void{global$n;if(!$v)throw new RuntimeException($l);$n++;echo"OK $l\n";}
function denied(int$status,callable$f,string$l):void{try{$f();}catch(PortalError$e){ok($e->status===$status,$l);return;}throw new RuntimeException($l);}
$u=$db->query("SELECT id,auth_version FROM pisco_users WHERE username='admin'")->fetch();$_SESSION['user_id']=(int)$u['id'];$_SESSION['auth_version']=(int)$u['auth_version'];$original=$db->query('SELECT data FROM pisco_state WHERE id=1')->fetchColumn();$accounts=$db->query('SELECT id,username,password,role,profile,active FROM pisco_users ORDER BY id')->fetchAll();$before=json_decode($original,true);if(!$before['reclamos'])throw new RuntimeException('Falta reclamo de pruebas.');$id=$before['reclamos'][0]['id'];unset($before['reclamos'][0]['cargoCod']);$db->prepare('UPDATE pisco_state SET data=?,revision=revision+1 WHERE id=1')->execute([json_encode($before)]);
try{PortalSchema::apply($db);$after=json_decode($db->query('SELECT data FROM pisco_state WHERE id=1')->fetchColumn(),true);$row=PortalPolicy::find($after['reclamos'],'id',$id);ok((bool)preg_match('/^[A-F0-9]{16}$/',$row['cargoCod']),'Reclamo anterior recibe código de verificación persistente');$clean=$after;foreach($clean['reclamos']as$i=>&$r){if(!isset($before['reclamos'][$i]['cargoCod']))unset($r['cargoCod']);}unset($r);ok($clean===$before,'Se conservan seguimiento, documentos, estados y contenido anterior');$state=$db->query('SELECT data,revision FROM pisco_state WHERE id=1')->fetch();PortalSchema::apply($db);ok($state===$db->query('SELECT data,revision FROM pisco_state WHERE id=1')->fetch(),'Repetir actualización conserva códigos y revisión');ok($accounts===$db->query('SELECT id,username,password,role,profile,active FROM pisco_users ORDER BY id')->fetchAll(),'Actualización conserva cuentas, contraseñas y roles');
foreach([$row['numDoc'],$row['cargoCod']]as$key)ok($app->lookup('reclamos',['reference'=>strtolower(' '.$row['codigo'].' '),'document'=>$key])['record']['id']===$id,'Consulta autorizada por documento o verificación');$short=preg_replace('/^(RCL|LR)-(\d{4})-0*(\d+)$/','$1-$2-$3',$row['codigo']);ok($app->lookup('reclamos',['reference'=>$short,'document'=>$row['numDoc']])['record']['id']===$id,'Consulta tolera ceros iniciales del correlativo');denied(422,fn()=>$app->lookup('reclamos',['reference'=>$row['codigo'],'document'=>'01']),'Folios 01 muestra validación, no un falso fallo de búsqueda');denied(404,fn()=>$app->lookup('reclamos',['reference'=>$row['codigo'],'document'=>'INVALID0000000000']),'Código incorrecto no revela el reclamo');$b=$app->bootstrap();$d=$b['data'];foreach($d['reclamos']as&$r)if($r['id']===$id)$r['cargoCod']='ABCDEF1234567890';unset($r);denied(422,fn()=>$app->save(['data'=>$d,'revision'=>$b['revision']]),'Código de verificación no es editable');$case=$after;foreach($case['reclamos']as&$r)if($r['id']===$id){$r['tipoDoc']='Pasaporte';$r['numDoc']='ab123456';}unset($r);$db->prepare('UPDATE pisco_state SET data=?,revision=revision+1 WHERE id=1')->execute([json_encode($case)]);ok($app->lookup('reclamos',['reference'=>$row['codigo'],'document'=>'AB123456'])['record']['id']===$id,'Consulta de pasaporte admite mayúsculas y minúsculas');}
finally{$db->prepare('UPDATE pisco_state SET data=?,revision=revision+1 WHERE id=1')->execute([$original]);PortalSchema::apply($db);}echo"\n$n comprobaciones del Libro de Reclamaciones aprobadas.\n";ob_end_flush();
